func testBaseChannelCommand() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRBaseClusterChannel(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterChannel init")
        return
    }
    cluster.cancelRecordProgram(with: MTRChannelClusterCancelRecordProgramParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.changeByNumber(with: MTRChannelClusterChangeChannelByNumberParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.changeByNumber(with: MTRChannelClusterChangeChannelByNumberParams(), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.change(with: MTRChannelClusterChangeChannelParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.change(with: MTRChannelClusterChangeChannelParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.getProgramGuide(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.getProgramGuide(with: MTRChannelClusterGetProgramGuideParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.recordProgram(with: MTRChannelClusterRecordProgramParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.skip(with: MTRChannelClusterSkipChannelParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.skip(with: MTRChannelClusterSkipChannelParams(), completionHandler: { err in mtrExpectInvalidState(err) })
}

